//! D10 lexicon: the embedded word tables and the English-versus-Vietnamese score.
//!
//! Everything here is `static` data in the binary (`include_str!`/`include_bytes!`
//! of files generated by `scripts/gen_wordlists.py`); nothing is built at run
//! time, nothing allocates. Lookups are binary searches over sorted text and
//! only run at a word break (or, for [`rime_prefix_ok`], on a 112-entry sorted
//! array). Sources and licences: `crates/vkb-core/data/THIRD_PARTY.md`.
//!
//! **Syllable key.** A Vietnamese syllable is looked up by an ASCII key: each
//! letter lowercased, then its mark (`^` circumflex, `(` breve, `+` horn), `đ`
//! is `D`, and the tone digit (`1` sắc … `5` nặng, none = no digit) at the very
//! end. `tiếng` is `tie^ng1`. Tone placement (old or new style) never matters.

use crate::letters::{Letter, Mark, Tone};

mod consts {
    include!("../data/consts.rs");
}
use consts::RIME_PREFIXES;

static ENGLISH: &str = include_str!("../data/english.txt");
static VI: &str = include_str!("../data/vi.txt");

/// FNV-1a 32-bit, the hash `pairs.bin` is keyed by.
pub const FNV_BASIS: u32 = 0x811C_9DC5;

pub fn fnv_extend(mut hash: u32, bytes: &[u8]) -> u32 {
    for &byte in bytes {
        hash = (hash ^ u32::from(byte)).wrapping_mul(0x0100_0193);
    }
    hash
}

/// An English word that Telex would compose into something else.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct EnglishWord {
    /// 1..=7: SCOWL size 10, 20, 35, 40, 50, 55, 60 (tech words count as 2).
    pub level: u8,
    /// Vietnamese text borrows it as-is (`teen`, `mix`).
    pub loan: bool,
    /// A programming word (`cos`, `max`, `return`).
    pub tech: bool,
    /// A short code identifier (`res`, `os`, `buf`).
    pub ident: bool,
    /// A name or brand (`Mary`, `Asus`).
    pub name: bool,
}

/// Binary search over sorted lines. `key_len(line)` is the length of the part
/// of the line that is the sort key.
fn find_line<'a>(blob: &'a str, probe: &[u8], key_len: fn(&[u8]) -> usize) -> Option<&'a [u8]> {
    let bytes = blob.as_bytes();
    let (mut lo, mut hi) = (0usize, bytes.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let start = bytes[..mid].iter().rposition(|&b| b == b'\n').map_or(0, |p| p + 1);
        let end = bytes[start..].iter().position(|&b| b == b'\n').map_or(bytes.len(), |p| start + p);
        let line = &bytes[start..end];
        match line[..key_len(line)].cmp(probe) {
            std::cmp::Ordering::Equal => return Some(line),
            std::cmp::Ordering::Less => lo = end + 1,
            std::cmp::Ordering::Greater => hi = start,
        }
    }
    None
}

fn english_key_len(line: &[u8]) -> usize {
    line.len() - 1
}

fn vi_key_len(line: &[u8]) -> usize {
    line.iter().position(|&b| b == b' ').unwrap_or(line.len())
}

/// `word` is lowercase ASCII.
pub fn english_word(word: &[u8]) -> Option<EnglishWord> {
    let line = find_line(ENGLISH, word, english_key_len)?;
    let tag = *line.last()?;
    let plain = EnglishWord { level: 1, loan: false, tech: false, ident: false, name: false };
    Some(match tag {
        b'1'..=b'7' => EnglishWord { level: tag - b'0', ..plain },
        b'a'..=b'g' => EnglishWord { level: tag - b'a' + 1, loan: true, ..plain },
        b'h'..=b'n' => EnglishWord { level: tag - b'h' + 1, ident: true, tech: true, ..plain },
        b'o'..=b'u' => EnglishWord { level: tag - b'o' + 1, name: true, ..plain },
        _ => EnglishWord { level: tag.wrapping_sub(b'A') + 1, tech: true, ..plain },
    })
}

/// How often the corpora saw the syllable (0 = not a common Vietnamese word).
pub fn vi_count(key: &[u8]) -> u32 {
    let Some(line) = find_line(VI, key, vi_key_len) else {
        return 0;
    };
    line[vi_key_len(line) + 1..]
        .iter()
        .fold(0u32, |acc, &d| acc * 10 + u32::from(d.wrapping_sub(b'0')))
}

/// English words that mark the previous word as English even when they are also
/// plausible Vietnamese toneless syllables. Sorted.
static FUNCTION_WORDS: &[&str] = &[
    "and", "any", "are", "at", "be", "but", "by", "each", "for", "from", "have", "her", "his", "how", "in", "is", "it", "its", "many", "my", "not", "of", "on", "or", "our", "she", "some", "such", "that", "the", "their", "them", "then", "there", "these", "they", "this", "those", "up", "was", "were", "what", "when", "where", "which", "who", "will", "with", "would", "you", "your",
];

pub fn is_function_word(word: &[u8]) -> bool {
    FUNCTION_WORDS.binary_search_by(|w| w.as_bytes().cmp(word)).is_ok()
}

/// Write the syllable key of `letters` (+ `tone`) into `out`; returns its length.
/// `None` when a letter has no ASCII form or the word is longer than `out`.
pub fn syllable_key(letters: &[Letter], tone: Tone, out: &mut [u8; 48]) -> Option<usize> {
    let mut len = 0usize;
    for letter in letters {
        let base = letter.base();
        if !base.is_ascii_alphabetic() {
            return None;
        }
        let need = 2;
        if len + need + 1 > out.len() {
            return None;
        }
        if base == 'd' && letter.mark == Mark::Bar {
            out[len] = b'D';
            len += 1;
            continue;
        }
        out[len] = base as u8;
        len += 1;
        match letter.mark {
            Mark::Circumflex => {
                out[len] = b'^';
                len += 1;
            }
            Mark::Breve => {
                out[len] = b'(';
                len += 1;
            }
            Mark::Horn => {
                out[len] = b'+';
                len += 1;
            }
            Mark::Bar | Mark::None => {}
        }
    }
    if tone != Tone::None {
        out[len] = b'0' + tone.index() as u8;
        len += 1;
    }
    Some(len)
}

/// `true` when the mark-free, tone-free rime `plain` (the letters after the
/// onset) is a prefix of some Vietnamese rime.
pub fn rime_prefix_ok(plain: &[u8]) -> bool {
    if plain.len() > 5 {
        return false;
    }
    let mut code = 0u32;
    for &byte in plain {
        let symbol = match byte {
            b'a' => 1,
            b'e' => 2,
            b'i' => 3,
            b'o' => 4,
            b'u' => 5,
            b'y' => 6,
            b'c' => 7,
            b'h' => 8,
            b'm' => 9,
            b'n' => 10,
            b'p' => 11,
            b't' => 12,
            b'g' => 13,
            _ => return false,
        };
        code = code * 14 + symbol;
    }
    RIME_PREFIXES.binary_search(&code).is_ok()
}

// ---------------------------------------------------------------------------
// The score
// ---------------------------------------------------------------------------

/// What stands left of the word being decided.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Left {
    /// Start of a line or sentence (after `. ! ?`, Enter, a caret move or a focus change).
    Start,
    /// After a comma, semicolon or colon: no left word to use, but not a sentence start.
    Clause,
    /// Right after a code operator or bracket (`x = `, `foo(`, `a + `).
    Code,
    /// The previous word was an English function word (`the`, `my`, `with`).
    Function,
    /// The previous word was English or code.
    English,
    /// The previous word was this Vietnamese syllable: its corpus count and the
    /// FNV state after `key + " "`.
    Vietnamese { count: u32, hash: u32 },
}

/// A Vietnamese syllable at least this common is "protected": it flips to
/// English only on positive English evidence (English or code on the left, a
/// code app at the start of a line, a known English collocation), never because
/// a word pair is missing from the table.
const PROTECTED_COUNT: u32 = 100;
const fn colloc(previous: &str, english: &str) -> u32 {
    let mut hash = fnv_const(FNV_BASIS, previous.as_bytes());
    hash = fnv_const(hash, b" ");
    fnv_const(hash, english.as_bytes())
}

const fn fnv_const(mut hash: u32, bytes: &[u8]) -> u32 {
    let mut i = 0;
    while i < bytes.len() {
        hash = (hash ^ bytes[i] as u32).wrapping_mul(0x0100_0193);
        i += 1;
    }
    hash
}

/// Vietnamese word + English word pairs that are real Vietnamese usage of an
/// English word: `previous syllable key + " " + english word`. Small on purpose;
/// these beat the protection of a common Vietnamese reading (`tên`).
static COLLOCATIONS: [u32; 6] = [
    colloc("hay", "mix"),
    colloc("tuo^i3", "teen"),
    colloc("nhom1", "teen"),
    colloc("kie^u3", "teen"),
    colloc("cach1", "teen"),
    colloc("thich1", "mix"),
];

/// Vietnamese word + English-looking word pairs that are really Vietnamese
/// (`nước mix` is `nước mĩ`): they force the Vietnamese reading.
static VI_COLLOCATIONS: &[u32] = &[
    colloc("nu+o+c1", "mix"),
    colloc("nguo+i2", "mix"),
    colloc("quo^c1", "mix"),
];

/// Known acronyms typed in capitals (`USA`, `UX`, `OS`): Telex would turn the
/// vowel and the S into `ÚA`, `Ũ`, `Ó`. Matched case-sensitively (letters and
/// digits, 2 to 5 characters).
static ACRONYMS: &[&str] = &[
    "AI", "API", "AR", "ASAP", "AWS", "B2B", "B2C", "CEO", "CFO", "CH4", "CMS", "CO2", "COO",
    "CPU", "CRM", "CSS", "CTO", "DAX", "DNS", "EU", "EXO", "FAQ", "FTP", "GCP", "GIF", "GPS",
    "GPU", "H2O", "HDD", "HDMI", "HR", "HTML", "HTTP", "HTTPS", "IDE", "IMF", "IP", "IT", "JPG",
    "JPEG", "JSON", "KPI", "LAN", "LCD", "LED", "LLM", "MP3", "MP4", "NASA", "NFT", "NO2", "O2",
    "OCR", "OKR", "OS", "OTP", "PDF", "PM", "PNG", "PR", "QA", "QR", "RAM", "REST", "ROI", "ROM",
    "SAS", "SDK", "SEO", "SMS", "SO2", "SOS", "SQL", "SSD", "SSH", "SSL", "SVG", "TCP", "TLS",
    "TOS", "UDP", "UI", "UK", "UN", "URI", "URL", "US", "USA", "USB", "UX", "VPN", "VR", "WAN",
    "XML", "XR",
];

/// Lowercase tokens that are clearly not Vietnamese words.
static LOWER_ACRONYMS: &[&str] = &["asap", "sos", "usa"];

/// `token` is a known acronym typed the way acronyms are: capitals, or one of
/// the few lowercase ones that are unmistakable.
pub fn is_acronym(token: &[u8]) -> bool {
    if token.len() < 2 || token.len() > 5 {
        return false;
    }
    ACRONYMS.iter().any(|a| a.as_bytes() == token)
        || LOWER_ACRONYMS.iter().any(|a| a.as_bytes() == token)
}

/// Should the typed English word replace the composed text?
///
/// The rule is conservative. **A plausible Vietnamese syllable wins** (in the
/// corpus list or only well-formed), in every app. It flips only on positive
/// evidence: an English function word or English word on the left, a code
/// context, a known collocation, or the keyword `if` at a line start. When the
/// composed text cannot be Vietnamese (`ủe`, `wể`, `pas`) the list decides.
/// The app profile alone never flips anything; a code editor only lets a code
/// identifier (`res`, `os`) stand after a code word, bracket or operator.
///
/// `vi_key` is the composed Vietnamese syllable's key, `typed` the lowercase
/// typed keys, `plausible` whether the composed text could be Vietnamese.
pub fn english_wins(vi_key: &[u8], typed: &[u8], word: EnglishWord, left: Left, code_app: bool, plausible: bool) -> bool {
    let count = vi_count(vi_key);
    let protected = count >= PROTECTED_COUNT;
    // A rarer English form (plural, rare word) against a real Vietnamese word.
    let weak = word.level > 2 && !word.loan && !word.name && count > 0;
    if word.ident && code_app && matches!(left, Left::English | Left::Code | Left::Function) {
        return true;
    }
    if let Left::Vietnamese { hash, .. } = left {
        let phrase = fnv_extend(hash, typed);
        if VI_COLLOCATIONS.contains(&phrase) {
            return false;
        }
        if COLLOCATIONS.contains(&phrase) {
            return true;
        }
    }
    if !plausible {
        return true;
    }
    match left {
        // `the car`, `my tips`, `with cups`: an English noun, even a plural or a
        // word that collides with a common Vietnamese one.
        Left::Function => !(protected && (word.level > 2 || word.loan)),
        // `I like mix`, but `test có xanh` and `hook sẽ chạy` stay Vietnamese.
        Left::English => !protected && !weak,
        // `x = max`, `foo(cos`: a code context.
        Left::Code => !protected || (code_app && word.tech),
        // A keyword whose Vietnamese twin is rare (`ì`).
        Left::Start => typed == b"if",
        Left::Clause | Left::Vietnamese { .. } => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables_are_sorted_and_findable() {
        assert_eq!(english_word(b"user").map(|w| (w.level, w.loan)), Some((1, false)));
        assert_eq!(english_word(b"teen").map(|w| (w.level, w.loan)), Some((3, true)));
        assert!(english_word(b"res").unwrap().ident);
        assert!(english_word(b"harry").unwrap().name);
        assert!(english_word(b"cos").unwrap().tech);
        assert_eq!(english_word(b"zzzz"), None);
        assert!(vi_count(b"co1") > 1000);
        assert_eq!(vi_count(b"zzzz"), 0);
        for window in ENGLISH.lines().collect::<Vec<_>>().windows(2) {
            assert!(window[0][..window[0].len() - 1] < window[1][..window[1].len() - 1]);
        }
    }

    #[test]
    fn rime_prefixes() {
        for ok in ["u", "uo", "uon", "uong", "ie", "iec", "yeu", "oanh", "a"] {
            assert!(rime_prefix_ok(ok.as_bytes()), "{ok}");
        }
        for bad in ["uit", "oo", "ay" , "aa", "ib", "uoo", "ot", "eeee"] {
            // "ay" and "ot" are real rimes: only the genuinely impossible ones fail.
            let real = matches!(bad, "ay" | "ot");
            assert_eq!(rime_prefix_ok(bad.as_bytes()), real, "{bad}");
        }
    }

    #[test]
    fn function_words_are_sorted() {
        assert!(FUNCTION_WORDS.windows(2).all(|w| w[0] < w[1]));
    }
}
